<?php
require_once __DIR__.'/../lib/bootstrap.php'; require_role('teacher','admin');
$uid=(int)current_user()['id'];$eid=get_int('exam_id');$owner=current_user()['role']==='admin'?'':' AND e.created_by=?';$params=current_user()['role']==='admin'?[$eid]:[$eid,$uid];
$s=db()->prepare("SELECT e.*,s.title subject_title,c.title class_title FROM exams e JOIN subjects s ON s.id=e.subject_id JOIN classes c ON c.id=e.class_id WHERE e.id=?$owner");$s->execute($params);$exam=$s->fetch();if(!$exam)exit('آزمون پیدا نشد یا دسترسی ندارید.');
$s=db()->prepare('SELECT a.*,u.full_name,u.mobile FROM attempts a JOIN users u ON u.id=a.student_id WHERE a.exam_id=? ORDER BY a.score DESC,u.full_name');$s->execute([$eid]);$attempts=$s->fetchAll();$scores=array_values(array_filter(array_map(fn($a)=>$a['score']===null?null:(float)$a['score'],$attempts),fn($v)=>$v!==null));$avg=$scores?array_sum($scores)/count($scores):0;$min=$scores?min($scores):0;$max=$scores?max($scores):0;
$s=db()->prepare('SELECT q.id,q.question_text,q.chapter,q.score,q.question_type,COUNT(a.id) responses,SUM(CASE WHEN a.is_correct=1 THEN 1 ELSE 0 END) correct_count,COALESCE(SUM(a.awarded_score),0) awarded FROM questions q LEFT JOIN answers a ON a.question_id=q.id LEFT JOIN attempts at ON at.id=a.attempt_id AND at.exam_id=? WHERE q.exam_id=? GROUP BY q.id ORDER BY q.sort_order');$s->execute([$eid,$eid]);$questionStats=$s->fetchAll();
$chapterStats=[];$typeStats=[];foreach($questionStats as $q){$chapter=trim((string)($q['chapter']??''));if($chapter==='')$chapter='بدون فصل / مبحث';$rate=(int)$q['responses']>0?(int)$q['correct_count']/(int)$q['responses']*100:0;if(!isset($chapterStats[$chapter]))$chapterStats[$chapter]=['questions'=>0,'responses'=>0,'success_sum'=>0,'score'=>0,'max'=>0];$chapterStats[$chapter]['questions']++;$chapterStats[$chapter]['responses']+=(int)$q['responses'];$chapterStats[$chapter]['success_sum']+=$rate;$chapterStats[$chapter]['score']+=(float)$q['awarded'];$chapterStats[$chapter]['max']+=(float)$q['score']*(int)$q['responses'];$type=$q['question_type'];if(!isset($typeStats[$type]))$typeStats[$type]=['questions'=>0,'responses'=>0,'correct'=>0];$typeStats[$type]['questions']++;$typeStats[$type]['responses']+=(int)$q['responses'];$typeStats[$type]['correct']+=(int)$q['correct_count'];}
$title='گزارش آزمون';require __DIR__.'/../partials/header.php';?><div class="card class-toolbar"><div><span class="eyebrow">گزارش آموزشی</span><h1>گزارش آزمون</h1><p class="muted"><?=e($exam['title'])?> — <?=e($exam['subject_title'])?> — <?=e($exam['class_title'])?></p></div><div class="actions"><a class="btn btn-light" href="<?=e(url('teacher/exams.php?id='.$eid))?>">بازگشت</a><a class="btn btn-success" href="<?=e(url('teacher/exam_report_export.php?exam_id='.$eid))?>">خروجی Excel</a><button class="btn btn-primary" onclick="window.print()">چاپ گزارش</button></div></div><div class="grid grid-4"><div class="card stat"><span>تعداد شرکت‌کنندگان</span><strong><?=count($attempts)?></strong></div><div class="card stat"><span>میانگین نمره</span><strong><?=format_score($avg)?></strong></div><div class="card stat"><span>بیشترین نمره</span><strong><?=format_score($max)?></strong></div><div class="card stat"><span>کمترین نمره</span><strong><?=format_score($min)?></strong></div></div><div class="card"><h2>فهرست دانش‌آموزان</h2><table class="table"><thead><tr><th>ردیف</th><th>دانش‌آموز</th><th>شماره</th><th>نمره</th><th>درصد</th><th>وضعیت</th></tr></thead><tbody><?php foreach($attempts as $i=>$a):?><tr><td><?=($i+1)?></td><td><?=e($a['full_name'])?></td><td><?=e($a['mobile'])?></td><td><?=format_score($a['score']??0)?> / <?=format_score($exam['total_score'])?></td><td><?=format_score($a['percentage']??0)?>%</td><td><?=e($a['status'])?></td></tr><?php endforeach;?></tbody></table></div><div class="card"><h2>تحلیل بر اساس نوع سؤال</h2><table class="table"><thead><tr><th>نوع سؤال</th><th>تعداد سؤال</th><th>تعداد پاسخ</th><th>درصد موفقیت</th></tr></thead><tbody><?php $labels=['mcq'=>'چهارگزینه‌ای','true_false'=>'صحیح/غلط','short'=>'پاسخ کوتاه'];foreach($typeStats as $type=>$st):$rate=$st['responses']>0?$st['correct']/$st['responses']*100:0;?><tr><td><?=e($labels[$type]??$type)?></td><td><?=$st['questions']?></td><td><?=$st['responses']?></td><td><?=format_score($rate)?>%</td></tr><?php endforeach;?></tbody></table></div><div class="card"><h2>تحلیل فصل و مبحث</h2><p class="muted">فصل‌هایی با موفقیت کمتر از ۵۰٪ به تمرین و مرور بیشتری نیاز دارند.</p><table class="table"><thead><tr><th>فصل / مبحث</th><th>تعداد سؤال</th><th>تعداد پاسخ</th><th>میانگین موفقیت</th><th>وضعیت</th></tr></thead><tbody><?php foreach($chapterStats as $chapter=>$st):$rate=$st['questions']>0?$st['success_sum']/$st['questions']:0;$status=$rate>=80?'قوی':($rate>=50?'نیازمند مرور':'نیازمند تمرین بیشتر');?><tr><td><?=e($chapter)?></td><td><?=$st['questions']?></td><td><?=$st['responses']?></td><td><?=format_score($rate)?>%</td><td><?=e($status)?></td></tr><?php endforeach;?></tbody></table></div><div class="card"><h2>تحلیل سؤال‌ها</h2><table class="table"><thead><tr><th>شماره</th><th>نوع</th><th>فصل</th><th>پرسش</th><th>تعداد پاسخ</th><th>درصد موفقیت</th></tr></thead><tbody><?php foreach($questionStats as $i=>$q):$rate=(int)$q['responses']>0?((int)$q['correct_count']/(int)$q['responses']*100):0;?><tr><td><?=($i+1)?></td><td><?=e($labels[$q['question_type']]??$q['question_type'])?></td><td><?=e($q['chapter']??'—')?></td><td><?=e(mb_strimwidth($q['question_text'],0,90,'...','UTF-8'))?></td><td><?=e($q['responses'])?></td><td><?=format_score($rate)?>%</td></tr><?php endforeach;?></tbody></table></div><?php require __DIR__.'/../partials/footer.php'; ?>
